mod tests {
    use super::*;

    #[test]
    fn extract_json_tolerates_fences_and_prose() {
        let s = "好的, 结果如下:\n```json\n[{\"a\":1},{\"b\":\"]x\"}]\n```\n完毕";
        let j = extract_balanced_json(s).unwrap();
        assert_eq!(j, "[{\"a\":1},{\"b\":\"]x\"}]");
        let obj = extract_balanced_json("noise {\"k\": \"v}v\"} tail").unwrap();
        assert_eq!(obj, "{\"k\": \"v}v\"}");
    }
}

