//! Host input conversion; no provider aliases or attachment paths are guessed.
use super::{client::Client, protocol::{Command, Empty, Model, SessionOptions}};
use super::super::{TurnRequest, PermissionMode};

pub fn options(client: &Client, input: &TurnRequest) -> anyhow::Result<SessionOptions> {
    let model = match &input.model {
        None => None,
        Some(serde_json::Value::String(id)) => {
            // Existing POLARIS_*_MODEL values contain only an ID. Resolve it only
            // when the daemon catalog identifies exactly one provider.
            let catalog = client.call(Command::Models(Empty {}))?;
            let models: Vec<Model> = serde_json::from_value(catalog.get("models").cloned()
                .ok_or_else(|| anyhow::anyhow!("AgentdMissingModels"))?
                .as_array().ok_or_else(|| anyhow::anyhow!("AgentdInvalidModels"))?
                .iter().map(|m| serde_json::json!({"provider":m["provider"], "id":m["id"]})).collect::<Vec<_>>().into())?;
            let current = crate::provider::current_provider_id();
            let selected = crate::provider::pi_translate::credential_id(&current);
            let preferred = models.iter().find(|m| &m.id == id && m.provider == selected).cloned();
            let mut matches = models.into_iter().filter(|m| &m.id == id);
            let model = matches.next().ok_or_else(|| anyhow::anyhow!("AgentdModelNotFound: {id}"))?;
            anyhow::ensure!(preferred.is_some() || matches.next().is_none(), "AgentdModelAmbiguous: specify provider and id");
            Some(preferred.unwrap_or(model))
        }
        Some(value) => Some(serde_json::from_value::<Model>(value.clone())?),
    };
    if let Some(model) = &model {
        anyhow::ensure!(!model.provider.is_empty() && !model.id.is_empty(), "AgentdInvalidModel");
    }
    Ok(SessionOptions { model, thinking_level: input.thinking_level.clone(),
        permission_mode: Some(match input.permission {
            PermissionMode::Deny => super::protocol::PermissionMode::Deny,
            PermissionMode::Manual => super::protocol::PermissionMode::Manual,
            PermissionMode::AutoCurrent => super::protocol::PermissionMode::AutoCurrent,
            PermissionMode::AutoAll => super::protocol::PermissionMode::AutoAll,
        }), sandbox: None, expert_prompt: None,
        tool_profile: Some(match input.permission { PermissionMode::Deny => "readonly", _ => "workspace" }.into()) })
}
//! Map Polaris keys to daemon UUIDs; never pass a conversation ID as a new UUID.
use super::{client::Client, protocol::{Command, Open, Session, Configure, SessionOptions}};
use super::super::TurnRequest;
use serde::{Serialize, Deserialize};
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::path::PathBuf;
#[derive(Clone, Serialize, Deserialize)]
pub struct SessionInfo { pub id: String, pub cwd: PathBuf, pub model: Value, pub tools: Vec<String> }
fn path(client: &Client, key: &str) -> PathBuf {
    client.config.session_map.join(format!("{:x}.json", Sha256::digest(key.as_bytes())))
}
pub fn open(client: &Client, input: &TurnRequest, tools: super::super::ToolOptions) -> anyhow::Result<SessionInfo> {
    let mut options = super::input::options(client, input)?;
    options.sandbox = Some(tools.sandbox);
    options.expert_prompt = Some(tools.expert_prompt.unwrap_or_default());
    let file = path(client, &input.session_id);
    let previous: Option<SessionInfo> = match std::fs::read(&file) {
        Ok(bytes) => Some(serde_json::from_slice(&bytes)?),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => None,
        Err(e) => return Err(e.into()),
    };
    let cwd = std::fs::canonicalize(&input.cwd)?;
    let id = previous.as_ref().map(|s| s.id.clone());
    if let Some(previous) = &previous {
        if previous.cwd != cwd { let _ = client.call(Command::Close(Session { session_id: previous.id.clone() })); }
    }
    let response = client.call(Command::Open(Open { session_id: id, cwd: Some(cwd.to_string_lossy().into()), options: options.clone() }));
    let response = match response {
        Ok(v) => v,
        Err(e) if e.to_string().starts_with("SESSION_ALREADY_OPEN:") => {
            let previous = previous.as_ref().ok_or_else(|| anyhow::anyhow!("AgentdSessionMappingMissing"))?;
            client.call(Command::Configure(Configure { session_id: previous.id.clone(), options: options.clone() }))?
        }
        Err(e) if e.to_string().starts_with("SESSION_NOT_FOUND:") => {
            client.call(Command::Open(Open { session_id: None, cwd: Some(cwd.to_string_lossy().into()), options: options.clone() }))?
        }
        Err(e) => return Err(e),
    };
    anyhow::ensure!(response.get("reopenRequired") != Some(&Value::Bool(true)), "AgentdSessionReopenRequired");
    let info = SessionInfo {
        id: response.get("sessionId").and_then(Value::as_str).ok_or_else(|| anyhow::anyhow!("AgentdMissingSessionId"))?.into(),
        cwd, model: response.get("model").cloned().ok_or_else(|| anyhow::anyhow!("AgentdMissingModel"))?,
        tools: serde_json::from_value(response.get("tools").cloned().ok_or_else(|| anyhow::anyhow!("AgentdMissingTools"))?)?,
    };
    std::fs::create_dir_all(&client.config.session_map)?;
    let temporary = file.with_extension("tmp");
    std::fs::write(&temporary, serde_json::to_vec(&info)?)?;
    std::fs::rename(temporary, file)?;
    Ok(info)
}
pub fn close(client: &Client, key: &str) -> anyhow::Result<()> {
    let file = path(client, key);
    if !file.exists() { return Ok(()); }
    let info: SessionInfo = serde_json::from_slice(&std::fs::read(&file)?)?;
    match client.call(Command::Close(Session { session_id: info.id })) {
        Err(e) if !e.to_string().starts_with("SESSION_NOT_FOUND:") => Err(e),
        _ => Ok(()),
    }
}

/// The SDK is authoritative for busy detection; an active turn rejects configuration.
pub fn configure(client: &Client, key: &str, options: SessionOptions) -> anyhow::Result<Value> {
    let info: SessionInfo = serde_json::from_slice(&std::fs::read(path(client, key))?)?;
    client.call(Command::Configure(Configure { session_id: info.id, options }))
}
use super::protocol::{Event, TurnStatus};
use crate::chat::{backend::event, artifacts::{is_displayable_artifact, packaged_project_root}, ChatStreamEvent};
use std::{path::PathBuf, collections::HashMap, time::{Duration, Instant}};
use super::super::config::Agentd;

pub struct Translator {
    req: String, conv: Option<String>, cwd: PathBuf,
    tools: HashMap<String, String>, write_tools: Vec<String>,
    delta: String, last_flush: Instant, window: Duration, max_bytes: usize,
    error_seen: bool, done: bool,
    provider: Option<String>, failure_code: Option<String>,
}
impl Translator {
    pub fn new(req: String, conv: Option<String>, cwd: PathBuf, config: &Agentd) -> Self {
        Self { req, conv, cwd, tools: HashMap::new(), write_tools: config.write_tools.clone(),
            delta: String::new(), last_flush: Instant::now(), window: Duration::from_millis(config.delta_batch_ms),
            max_bytes: config.max_line_bytes, error_seen: false, done: false, provider: None, failure_code: None }
    }
    pub fn with_provider(mut self, id: &str) -> Self { self.provider = Some(id.into()); self }
    pub fn make(&self, kind: &str, text: Option<String>) -> ChatStreamEvent { event(&self.req, self.conv.as_deref(), kind, text) }
    pub fn flush(&mut self) -> Vec<ChatStreamEvent> {
        self.last_flush = Instant::now();
        if self.delta.is_empty() { vec![] } else {
            let text = std::mem::take(&mut self.delta);
            vec![self.make("delta", Some(text))]
        }
    }
    pub fn tick(&mut self) -> Vec<ChatStreamEvent> {
        if self.last_flush.elapsed() >= self.window { self.flush() } else { vec![] }
    }
    pub fn accept(&mut self, input: Event) -> Vec<ChatStreamEvent> {
        if self.done { return vec![]; }
        if let Event::Text { text } = input {
            let mut out = if self.delta.len() + text.len() > self.max_bytes { self.flush() } else { vec![] };
            self.delta.push_str(&text);
            out.extend(self.tick());
            return out;
        }
        let mut out = self.flush();
        match input {
            Event::PermissionRequest { target_session_id, call_id, tool, summary, expires_at, parent_call_id } => {
                out.push(self.make("permission.request", Some(serde_json::json!({
                    "sessionId": target_session_id, "callId": call_id, "tool": tool,
                    "summary": summary, "expiresAt": expires_at, "parentCallId": parent_call_id,
                }).to_string())));
            }
            Event::PermissionResolved { target_session_id, call_id, reason } => {
                out.push(self.make("permission.resolved", Some(serde_json::json!({
                    "sessionId": target_session_id, "callId": call_id, "reason": reason,
                }).to_string())));
            }
            Event::SandboxRequest { target_session_id, call_id, operation, args } => {
                out.push(self.make("sandbox.request", Some(serde_json::json!({
                    "sessionId": target_session_id, "callId": call_id, "operation": operation, "args": args,
                }).to_string())));
            }
            Event::ToolStarted { call_id, tool, args, parent_call_id } => {
                let path = args.get("path").and_then(|v| v.as_str());
                let summary = path.or_else(|| args.get("command").and_then(|v| v.as_str()))
                    .or_else(|| args.get("pattern").and_then(|v| v.as_str())).map(str::to_owned);
                let mut ev = self.make("tool", summary);
                ev.tool = Some(tool.clone());
                ev.call_id = Some(call_id.clone());
                ev.parent_call_id = parent_call_id;
                out.push(ev);
                if self.write_tools.contains(&tool) {
                    if let Some(path) = path {
                        self.tools.insert(call_id, self.cwd.join(path).to_string_lossy().replace('\\', "/"));
                    }
                }
            }
            Event::ToolCompleted { call_id, tool, is_error, .. } => {
                let path = self.tools.remove(&call_id);
                if is_error {
                    // A tool failure is visible, but the agent may recover and finish successfully.
                    out.push(self.make("error", Some(format!("ToolFailed: {tool} ({call_id})"))));
                } else if let Some(path) = path {
                    if is_displayable_artifact(&path) && packaged_project_root(std::path::Path::new(&path)).is_none() {
                        out.push(self.make("artifact", Some(path)));
                    }
                }
            }
            Event::Error { code, message } => {
                if crate::provider::pi_failure_counts(&code) { self.failure_code = Some(code.clone()); }
                self.error_seen = true;
                out.push(self.make("error", Some(format!("{code}: {message}"))));
            }
            Event::Completed { status } => {
                if let Some(provider) = self.provider.take() {
                    let code = self.failure_code.take();
                    let success = status == TurnStatus::Completed;
                    let failed = status == TurnStatus::Error;
                    std::thread::spawn(move || crate::provider::pi_outcome(&provider, success, failed, code.as_deref()));
                }
                if matches!(status, TurnStatus::Error | TurnStatus::Timeout) && !self.error_seen {
                    out.push(self.make("error", Some(format!("AgentdTurnFailed: {status:?}"))));
                }
                self.done = true;
                out.push(self.make("done", None));
            }
            // The current frontend contract has no reasoning/usage event. Future
            // support should extend it with optional fields, preserving existing consumers.
            Event::Reasoning { .. } | Event::Usage { .. } => {}
            Event::Started => {}
            Event::Text { .. } => {}
        }
        out
    }
}
