            let parent = path.parent().ok_or_else(|| anyhow::anyhow!("WikiInvalidPath"))?;
            let name = path.file_name().ok_or_else(|| anyhow::anyhow!("WikiInvalidPath"))?;
            Ok(canonical_new(parent)?.join(name))
        }
        Err(error) => Err(error.into()),
